// Finite State Machine to synchronously receive a byte with a start/stop bit
// (0->1->0->8->1) delimited by a high-to-low transition of the data line.
// Active-high synchronous reset.
module TopModule(input clk, input reset, input in, output reg done);
  reg [3:0] cnt;
  reg [7:0] byte;
  reg [1:0] state;
  always @(posedge clk) begin
    if (reset) begin
      cnt <= 4'd0;
      state <= 2'd0;
      done <= 1'b0;
    end else begin
      case (state)
        2'd0: begin // wait for start bit
          if (!in) state <= 2'd1;
        end
        2'd1: begin // wait for 8 data bits
          if (cnt == 4'd8) state <= 2'd2;
          else begin
            byte <= {in, byte[7:1]};
            cnt <= cnt + 4'd1;
          end
        end
        2'd2: begin // wait for stop bit
          if (in) done <= 1'b1;
          if (!in) begin
            cnt <= 4'd0;
            state <= 2'd0;
          end
        end
      endcase
    end
  end
endmodule

